/* Khaana - "Cook with what you have"
   Loads the curated recipe database, scores each recipe against the cook's
   pantry and constraints, and renders ranked suggestions.
   Everything here is client-side; the data files are the source of truth. */
(function () {
  'use strict';

  var PANTRY_URL = 'data/pantry.json?v=48f0f84c';
  // The light index, not the full database: the Cook page only needs
  // ingredient ids and tags to rank. Generated by tools/split-recipes.py.
  var RECIPES_URL = 'data/recipes-index.json?v=71c63520';
  var STORAGE_KEY = 'khaana.pantry.v1';
  // Below this share of a recipe's ingredients the suggestion stops being
  // useful — it is a shopping list with a photo attached.
  var MIN_PCT = 20;
  // Nothing is ticked on a first visit.
  //
  // A four-item starter pantry was tried and removed. It made the page look
  // busy before the reader had done anything, and worse, it scored every
  // search result against ingredients they had never chosen: searching
  // "biryani" returned dishes labelled 13% with a long Missing list, which
  // reads as though the search had been filtered by the pantry. An empty
  // pantry means the two routes stay visibly independent.
  var DEFAULT_PANTRY = [];
  // The size of the database is not something the page advertises. Any count
  // above this is reported as "100+" rather than exactly.
  var COUNT_CAP = 100;
  function shown(n) { return n > COUNT_CAP ? COUNT_CAP + '+' : String(n); }

  /* What a match is worth, by the pantry shelf the ingredient sits on.
   *
   * Counting every ingredient equally sounds fair and is not: spices are 40%
   * of all the essential lines in the database, and the median recipe is 38%
   * spices. A stocked masala dabba alone therefore scored 37% on the median
   * recipe and cleared the 20% floor on 533 of the 656 — before the cook owned
   * a single vegetable. Pork Bafat came back at 86% to a kitchen with no meat
   * in it.
   *
   * So the shelves that decide whether dinner is possible are worth more than
   * the ones that season it. Missing the chicken means a different dinner;
   * missing the ajwain means a slightly flatter one.
   *
   * This reweights within a recipe rather than between recipes: pct stays
   * earned/possible, so a dish that really is mostly spices — a chutney, a
   * masala — is unaffected. Only mixed lists change, which is the point. */
  var CAT_WEIGHT = {
    protein: 2.5,   // meat, fish and eggs — names the dish, substitutes for nothing
    pulses: 2.0,    // the dal is the centre of the plate as much as any meat
    veg: 1.6,
    grains: 1.5,    // no besan, no pakora
    spices: 0.4
    // aromatics, dairy and the sour/sweet/nut shelf stay at 1.0.
  };

  /* A few ingredients are filed by what they are made of rather than by the
   * job they do. Paneer and tofu are catalogued as dairy, next to butter and
   * cream, but nobody seasons a dish with paneer — it is the centre of the
   * plate exactly as chicken is, and a cook who has it is looking for the
   * dishes built on it. At the shelf weight of 1.0 a paneer-only pantry
   * returned nothing at all: the top paneer dish scored under the 20% floor
   * and was dropped.
   *
   * Ingredient beats shelf. Kept deliberately short — this is for ingredients
   * a dish is named after, not a second weighting system. */
  var ING_WEIGHT = {
    paneer: 2.5,
    tofu: 2.5
  };

  /* An ingredient that turns up everywhere identifies nothing. Green chilli is
   * in 288 of the 656 recipes and onion in 260 — on the vegetable shelf by
   * botany, but doing a spice's job in the kitchen. Lotus stem is in four
   * recipes and jackfruit in three, and a cook who ticks one of those has said
   * something very specific about what they want for dinner.
   *
   * So a centre-of-the-plate ingredient the database rarely calls for is worth
   * more than a common one. Measured against the database rather than listed
   * here, so it stays true as recipes are added, and applied upward only: the
   * alternative, taxing onion and tomato, cost a beginner with four things
   * ticked a third of their results to sharpen a case they are not in yet.
   *
   * Never applied to spices. A rare spice is still a seasoning — kewra water
   * does not become the point of the dish by being unusual. */
  var RARE_SHARE = 0.04;   // called for by under 4% of the database
  var RARE_BONUS = 1.4;
  var CENTRE_SHELVES = { protein: 1, pulses: 1, veg: 1, grains: 1 };

  var pantry = null;
  var recipes = [];
  var selected = new Set();

  var el = function (id) { return document.getElementById(id); };

  /* ---------- scoring ---------- */

  // A recipe ingredient is one of: have | substitute | missing.
  // Staples (salt, oil, water, sugar) are assumed present in every kitchen.
  function classify(ingId, has, staples, subs) {
    if (staples.indexOf(ingId) !== -1) return { state: 'have', staple: true };
    if (has.has(ingId)) return { state: 'have' };
    var options = subs[ingId] || [];
    for (var i = 0; i < options.length; i++) {
      if (has.has(options[i].id)) {
        return { state: 'substitute', via: options[i] };
      }
    }
    return { state: 'missing' };
  }

  function scoreRecipe(recipe, has, filters) {
    var staples = pantry.staples;
    var subs = pantry.substitutions;

    var lines = recipe.ingredients.map(function (ing) {
      var c = classify(ing.id, has, staples, subs);
      return {
        id: ing.id,
        name: nameFor(ing.id),
        qty: ing.qty,
        note: ing.note,
        essential: ing.essential !== false,
        state: c.state,
        staple: !!c.staple,
        via: c.via || null
      };
    });

    // Only non-staple lines count toward the match figure, otherwise every
    // recipe would score a free 15% for having salt.
    var counted = lines.filter(function (l) { return !l.staple; });
    var essentials = counted.filter(function (l) { return l.essential; });

    var earned = 0, possible = 0;
    counted.forEach(function (l) {
      // Essentials are weighted 1.0, optional extras 0.35: not having a
      // garnish should barely dent the score, missing the main pulse should.
      // Then by shelf, so the protein and the vegetables carry the score and
      // the spice rack stops carrying it. See CAT_WEIGHT.
      var w = (l.essential ? 1 : 0.35) * weightFor(l.id);
      l.weight = w;
      possible += w;
      if (l.state === 'have') earned += w;
      else if (l.state === 'substitute') earned += w * (1 - (l.via.penalty || 0.2));
    });

    var pct = possible > 0 ? Math.round((earned / possible) * 100) : 0;

    var missingEssential = essentials.filter(function (l) { return l.state === 'missing'; });
    var subbedEssential = essentials.filter(function (l) { return l.state === 'substitute'; });
    var missingAny = counted.filter(function (l) { return l.state === 'missing'; });

    return {
      recipe: recipe,
      lines: lines,
      pct: pct,
      missingEssential: missingEssential,
      subbedEssential: subbedEssential,
      missingAll: missingAny,
      excluded: excludedBy(recipe, filters)
    };
  }

  // "+ 10 hr soaking" after the minutes on a card.
  //
  // The minutes stay active minutes and so does the time filter: somebody
  // asking for a twenty-minute dinner means twenty minutes of their evening,
  // not twenty minutes of elapsed clock, and filtering on elapsed time would
  // hide every marinade in the collection from them. But sabudana khichdi is
  // thirty active minutes that begin five hours after you start, and a card
  // saying only "30 min" moves the surprise to the recipe page instead of
  // removing it.
  function waitNote(r) {
    if (!r.inactiveMinutes) return '';
    var m = r.inactiveMinutes, n;
    if (m >= 1440) {
      var d = Math.floor(m / 1440), h = Math.round((m % 1440) / 60);
      if (h === 24) { d += 1; h = 0; }
      n = d + (d === 1 ? ' day' : ' days') + (h ? ' ' + h + ' hr' : '');
    } else if (m >= 60) {
      n = (m % 60 ? Math.floor(m / 60) + ' hr ' + (m % 60) + ' min' : (m / 60) + ' hr');
    } else {
      n = m + ' min';
    }
    return ' + ' + n + ' ' + esc(r.inactiveLabel || 'resting');
  }

  /* Hard constraints. These remove a recipe rather than lowering its score,
   * because "vegan" and "I have 20 minutes" are not preferences you rank by.
   *
   * Each reason carries whether it is a miss of kind or a miss of fit, which
   * is what decides whether the dish is worth naming afterwards. Ticking
   * Soups rules out 636 recipes for not being soups, and "Ariselu — soup"
   * tells a reader nothing: they did not ask about a sweet. A soup that takes
   * forty minutes when they asked for thirty is the opposite — the dish they
   * wanted, missing by ten minutes, and worth saying out loud. */
  function reason(text, kind) { return { text: text, kind: kind }; }

  function excludedBy(recipe, f) {
    var reasons = [];
    var total = recipe.prepMinutes + recipe.cookMinutes;

    f.diets.forEach(function (d) {
      if (recipe.tags.indexOf(d) === -1) reasons.push(reason(labelForTag(d), 'kind'));
    });
    if (f.maxTime && total > f.maxTime) {
      reasons.push(reason('over ' + f.maxTime + ' min', 'fit'));
    }

    /* Healthier in 30 minutes, meaning half an hour of your attention. Total
     * time rather than cooking time, because a reader with half an hour has
     * half an hour and does not care which part of it is chopping.
     *
     * Soaking and resting are not counted, and six of the twenty-five want
     * some — kosambari an hour of it. They stay in because the card prints
     * "+ 60 soaking" beside the time either way, so the reader is told rather
     * than protected, and because a lentil salad you start before you leave
     * the house is exactly the kind of thing this filter should surface. */
    if (f.quickHealthy) {
      if (recipe.tags.indexOf('healthier') === -1) reasons.push(reason('healthier', 'kind'));
      if (total > 30) reasons.push(reason('over 30 min', 'fit'));
    }

    // Calories per serving. A hard filter on an estimate, so the panel says so:
    // figures marked + are floors, and a dish can scrape in that should not.
    var kc = recipe.nutrition && recipe.nutrition.kcal;
    if (f.maxKcal && typeof kc === 'number' && kc > f.maxKcal) {
      reasons.push(reason('over ' + f.maxKcal + ' kcal', 'fit'));
    }

    if (f.savedOnly && window.KhaanaSaved && !window.KhaanaSaved.has(recipe.id)) {
      reasons.push(reason('not saved', 'kind'));
    }

    if (f.protein) {
      // "medium" is medium-or-better, not exactly medium: someone asking for
      // a decent amount of protein does not want the high ones filtered out.
      var b = proteinBand(recipe.nutrition);
      var ok = f.protein === 'high' ? b === 'high' : (b === 'high' || b === 'medium');
      if (!ok) reasons.push(reason(PROTEIN_LABEL[f.protein].toLowerCase(), 'fit'));
    }

    return reasons;
  }

  /* ---------- lookups ---------- */

  // Which shelf an ingredient sits on, read from the pantry file rather than
  // listed again here, so a new ingredient is weighted the moment it is
  // catalogued. Every id in the database resolves; staples never reach this.
  var CAT_CACHE = null;
  // How many recipes call for each ingredient as an essential. Counted once,
  // from the same index the page is about to score against.
  var FREQ = null;
  function buildFreq() {
    FREQ = {};
    recipes.forEach(function (r) {
      r.ingredients.forEach(function (i) {
        if (i.essential === false) return;
        FREQ[i.id] = (FREQ[i.id] || 0) + 1;
      });
    });
  }

  var WEIGHT_CACHE = {};
  function weightFor(id) {
    if (WEIGHT_CACHE[id]) return WEIGHT_CACHE[id];
    if (!CAT_CACHE) {
      CAT_CACHE = {};
      pantry.categories.forEach(function (c) {
        c.items.forEach(function (i) { CAT_CACHE[i.id] = c.id; });
      });
    }
    if (!FREQ) buildFreq();

    var shelf = CAT_CACHE[id];
    var w = typeof ING_WEIGHT[id] === 'number' ? ING_WEIGHT[id] : CAT_WEIGHT[shelf];
    if (typeof w !== 'number') w = 1;
    // An ING_WEIGHT entry says "this is the centre of the plate" as much as a
    // shelf does, so paneer earns the bonus its dairy shelf would have denied.
    var centre = CENTRE_SHELVES[shelf] || typeof ING_WEIGHT[id] === 'number';
    if (centre && (FREQ[id] || 0) < recipes.length * RARE_SHARE) {
      w *= RARE_BONUS;
    }
    WEIGHT_CACHE[id] = w;
    return w;
  }

  var NAME_CACHE = {};
  function nameFor(id) {
    if (NAME_CACHE[id]) return NAME_CACHE[id];
    var found = id;
    pantry.categories.forEach(function (c) {
      c.items.forEach(function (i) { if (i.id === id) found = i.name; });
    });
    if (found === id) {
      // staples and anything not in the selectable catalogue
      found = id.replace(/-/g, ' ').replace(/\b\w/g, function (m) { return m.toUpperCase(); });
    }
    NAME_CACHE[id] = found;
    return found;
  }

  var TAG_LABELS = {
    vegetarian: 'vegetarian', vegan: 'vegan', 'gluten-free': 'gluten-free',
    'dairy-free': 'dairy-free', 'nut-free': 'nut-free', 'egg-free': 'egg-free',
    'no-onion-garlic': 'no onion/garlic', pescatarian: 'pescatarian',
    soup: 'soup', 'wellness-shot': 'wellness shot', healthier: 'healthier'
  };
  function labelForTag(t) { return TAG_LABELS[t] || t; }

  var EQUIP_LABELS = {
    stovetop: 'a stovetop', 'pressure-cooker': 'a pressure cooker', steamer: 'a steamer',
    blender: 'a blender', oven: 'an oven or grill', kadhai: 'a deep pan for frying',
    tawa: 'a flat griddle'
  };
  function labelForEquip(e) { return EQUIP_LABELS[e] || e; }

  /* ---------- rendering ---------- */

  /* ---------- the pantry picker ----------

     170 checkboxes in one flat list asked the cook to make 170 decisions of
     equal weight, and the data says they are nothing like equal. Spices are
     39% of every ingredient slot in the database, and nobody decides about
     turmeric on a Tuesday, you keep an Indian spice shelf or you do not.
     Ticking just these seven puts 226 of 586 recipes above the display floor
     on their own, up from 177 before mustard seeds joined them.

     So the picker asks three questions instead of one long one: do you keep a
     spice shelf, what fresh things do you have tonight, and (folded away) is
     there anything unusual in the cupboard. */
  var SHELF = ['turmeric', 'cumin-seeds', 'coriander-powder', 'chilli-powder',
               'black-pepper', 'garam-masala', 'mustard-seeds'];

  // The most-used things that are not shelf stock. Both rices are here: they
  // substitute for each other at a 0.20 penalty, so the matcher barely cares
  // which you own, but basmati is what most kitchens actually have and leaving
  // it out sent those cooks digging through a category to find it.
  var COMMON = ['onion', 'tomato', 'potato', 'ginger', 'garlic', 'green-chilli',
                'coriander-leaves', 'curry-leaves', 'chicken',
                'chana-dal', 'toor-dal', 'urad-dal', 'basmati-rice', 'rice',
                'atta', 'besan', 'maida', 'rice-flour'];

  function catalogue() {
    var out = [];
    pantry.categories.forEach(function (c) {
      c.items.forEach(function (i) {
        if (i.selectable !== false) out.push({ item: i, cat: c.label });
      });
    });
    return out;
  }

  function itemName(id) {
    var hit = catalogue().filter(function (e) { return e.item.id === id; })[0];
    return hit ? hit.item.name : nameFor(id);
  }

  // One ingredient can appear twice — once in the common grid, once in its
  // category — so every checkbox for an id has to move together.
  function syncChecks(id, on) {
    document.querySelectorAll('.cook-panel input[type="checkbox"][value="' + id + '"]')
      .forEach(function (b) { b.checked = on; });
  }

  function toggle(id, on) {
    if (on) selected.add(id); else selected.delete(id);
    syncChecks(id, on);
    persist();
    renderPicked();
    shelfButton();
    update();
  }

  function ingLabel(item) {
    var lab = document.createElement('label');
    lab.className = 'ing';
    var cb = document.createElement('input');
    cb.type = 'checkbox';
    cb.value = item.id;
    cb.checked = selected.has(item.id);
    cb.addEventListener('change', function () { toggle(item.id, cb.checked); });
    lab.appendChild(cb);
    lab.appendChild(document.createTextNode(item.name));
    return lab;
  }

  /* What is ticked, pinned above the list so it does not scroll out of sight. */
  function renderPicked() {
    var box = el('pantry-picked');
    if (!box) return;
    if (!selected.size) { box.hidden = true; box.innerHTML = ''; return; }
    box.hidden = false;
    box.innerHTML = Array.from(selected).map(itemName).sort().map(function (n, i) {
      var id = Array.from(selected).filter(function (x) { return itemName(x) === n; })[0];
      return '<button type="button" class="picked-chip" data-id="' + esc(id) +
             '" aria-label="Remove ' + esc(n) + '">' + esc(n) + ' <span aria-hidden="true">&times;</span></button>';
    }).join('');
    box.querySelectorAll('.picked-chip').forEach(function (b) {
      b.addEventListener('click', function () { toggle(b.getAttribute('data-id'), false); });
    });
  }

  function shelfHeld() {
    return SHELF.filter(function (id) { return selected.has(id); }).length;
  }

  function shelfButton() {
    var b = el('add-shelf'), note = el('shelf-note');
    if (!b) return;
    var held = shelfHeld(), all = held === SHELF.length;
    b.textContent = all ? '\u2713 Spice shelf added. Remove it'
                        : '+ I keep a standard spice shelf';
    b.classList.toggle('is-on', all);
    note.textContent = all
      ? 'The six spices almost every one of these recipes assumes.'
      : (held ? held + ' of the 6 already ticked. Add the rest in one go.'
              : 'Ticks the six spices almost every one of these recipes assumes.');
  }

  function renderCommon() {
    var wrap = el('pantry-common');
    if (!wrap) return;
    wrap.innerHTML = '';
    var known = {};
    catalogue().forEach(function (e) { known[e.item.id] = e.item; });
    // A <details> rather than a plain block: open on arrival because it is the
    // fastest way in, foldable afterwards because once it is set it is a long
    // list between the reader and everything below it.
    var group = document.createElement('details');
    group.className = 'pantry-group pantry-common-group pantry-cat';
    group.open = true;
    var sum = document.createElement('summary');
    var n = COMMON.filter(function (id) { return known[id]; }).length;
    sum.innerHTML = 'Most-used ingredients <span class="cat-n">' + n + '</span>';
    group.appendChild(sum);
    var list = document.createElement('div');
    list.className = 'pantry-items';
    COMMON.forEach(function (id) { if (known[id]) list.appendChild(ingLabel(known[id])); });
    group.appendChild(list);
    wrap.appendChild(group);
  }

  /* The long tail, folded away. Open on demand or by searching. */
  function renderGroups() {
    var wrap = el('pantry-groups');
    wrap.innerHTML = '';
    pantry.categories.forEach(function (cat) {
      var items = cat.items.filter(function (i) { return i.selectable !== false; });
      if (!items.length) return;
      var d = document.createElement('details');
      d.className = 'pantry-group pantry-cat';
      var sum = document.createElement('summary');
      sum.innerHTML = esc(cat.label) + ' <span class="cat-n">' + items.length + '</span>';
      d.appendChild(sum);
      var list = document.createElement('div');
      list.className = 'pantry-items';
      items.forEach(function (i) { list.appendChild(ingLabel(i)); });
      d.appendChild(list);
      wrap.appendChild(d);
    });
  }

  function renderPantry() {
    renderPicked();
    shelfButton();
    renderCommon();
    renderGroups();
  }

  function readFilters() {
    var diets = Array.prototype.slice
      .call(document.querySelectorAll('input[name="diet"]:checked'))
      .map(function (i) { return i.value; });
    var t = el('f-time').value;
    var kcalEl = el('f-kcal');
    var maxKcal = kcalEl && kcalEl.value ? parseInt(kcalEl.value, 10) : 0;
    return {
      diets: diets,
      protein: (el('f-protein') || {}).value || '',
      savedOnly: !!(el('f-saved') || {}).checked,
      quickHealthy: !!(el('f-quick') || {}).checked,
      maxKcal: maxKcal,
      maxTime: t ? parseInt(t, 10) : null
    };
  }

  // Text search over name, region and ingredient names. Matching is on the
  // recipe rather than the pantry, so it deliberately ignores the MIN_PCT floor
  // — someone looking up a dish by name wants to find it and see what it needs,
  // not be told they are short of it.
  function searchQuery() {
    var box = el('recipe-search');
    return box ? box.value.trim().toLowerCase() : '';
  }

  // Everything a cook might reasonably type: the dish, where it is from, what
  // it says it is, what goes in it, the diet tags, how hard it is and what it
  // needs to cook in. Tags are matched on their readable label as well as their
  // id, so "no onion" and "gluten free" both work.
  /* Three tiers, because where a word lands changes what it means: the dish
     name is what someone is usually typing, region and diet are how they
     narrow it, and the ingredient list is the long tail. */
  function doc(s) {
    if (s._doc) return s._doc;
    var r = s.recipe;
    var strong = [r.region, r.subtitle || '', r.difficulty || ''];
    (r.tags || []).forEach(function (t) { strong.push(t, labelForTag(t), t.replace(/-/g, ' ')); });
    (r.equipment || []).forEach(function (e) { strong.push(e, labelForEquip(e), e.replace(/-/g, ' ')); });
    (r.allergens || []).forEach(function (a) { strong.push(a); });
    var body = [];
    s.lines.forEach(function (l) { body.push(l.name, l.id.replace(/-/g, ' ')); });
    s._doc = window.KhaanaMatch.prepare({
      title: r.name, strong: strong.join(' '), body: body.join(' ')
    });
    return s._doc;
  }

  // Tokenising is the same work for every recipe in a pass, so it is done once
  // per distinct query rather than 536 times.
  var qParts = { q: null };
  function queryParts(q) {
    if (qParts.q !== q) {
      qParts = { q: q, toks: window.KhaanaMatch.tokens(q), phrase: window.KhaanaMatch.norm(q) };
    }
    return qParts;
  }

  /* How far inside the "healthier" definition a dish sits, as the sum of four
     figures each divided by its own ceiling in tools/tag-healthy.py. Lower is
     lighter. A dish at half of every limit comes out at 2.0 and one sitting on
     every limit at 4.0. A recipe with no nutrition sorts last rather than
     first, which is the safe direction for a health list. */
  function headroom(r) {
    // The index carries these flat rather than under perServing, which is the
    // shape the recipe detail file uses. Read the wrong one and every recipe
    // comes back Infinity, ties, and falls through to the clock.
    var n = r.nutrition;
    if (!n || typeof n.kcal !== 'number') return Infinity;
    return n.satFat / 7 + n.fat / 20 + n.kcal / 700 + (n.sugars || 0) / 12;
  }

  function queryScore(s, q) {
    if (!q) return 0;
    var p = queryParts(q);
    if (!p.toks.length) return 0;
    return window.KhaanaMatch.score(doc(s), p.toks, p.phrase);
  }

  function matchesQuery(s, q) {
    if (!q) return true;
    var p = queryParts(q);
    if (!p.toks.length) return true;
    return queryScore(s, q) > 0;
  }

  function update() {
    var filters = readFilters();
    var has = selected;
    var q = searchQuery();

    el('pantry-count').textContent = selected.size;
    syncPanelToggle();

    var scored = recipes.map(function (r) { return scoreRecipe(r, has, filters); });

    var eligible = scored.filter(function (s) { return s.excluded.length === 0; });
    var blocked = scored.filter(function (s) { return s.excluded.length > 0; });

    /* Searching or filtering is a different question from "what can I cook
     * with this". Someone who ticks Soups wants the soups — all of them, in a
     * sensible order — not the four soups they happen to have the shallots
     * for. So a query or a filter turns the pantry off entirely: no one-fifth
     * floor on the way in, and no pantry percentage in the sort.
     *
     * This used to name only the soup filter, and the other eight fell through
     * to the pantry comparator. With an empty pantry every recipe scores 0, so
     * the tie broke on the number of missing essential ingredients, which is
     * to say on the length of the ingredient list: ticking Healthier opened
     * with a 696 kcal plate of idli because idli has four ingredients. */
    var browsing = !!q || filters.quickHealthy || filters.diets.length > 0;

    /* Healthier is the one filter that is a gradient rather than a yes or no.
     * There is no more-vegan, so a vegan list is fine in any sensible order,
     * but a reader who asks for the lighter dishes means the lighter ones
     * first — not the quickest that happens to qualify.
     *
     * Ranked on the four figures tools/tag-healthy.py calls "the whole dial",
     * each as a fraction of the ceiling that tool sets, so the order says how
     * far inside its own definition a dish sits. Equal weights, because the
     * thresholds already carry the judgement about what matters.
     *
     * Typing the word counts as asking for it too. Someone who searches
     * "healthy" is making the same request as someone who ticks the box, and
     * getting the quickest qualifying dish back instead of the lightest was
     * the same defect wearing different clothes. */
    var healthFirst = filters.diets.indexOf('healthier') !== -1 ||
                      /\b(healthy|healthier)\b/.test(q);

    // A dish you have under a fifth of is a shopping list, not a suggestion.
    // Only applied once the cook has ticked something — before that every score
    // is 0 and this would empty the page.
    var sparse = [];
    if (selected.size > 0 && !browsing) {
      sparse = eligible.filter(function (s) { return s.pct < MIN_PCT; });
      eligible = eligible.filter(function (s) { return s.pct >= MIN_PCT; });
    }

    if (q) {
      eligible = eligible.filter(function (s) { return matchesQuery(s, q); });
      blocked = blocked.filter(function (s) { return matchesQuery(s, q); });
    }

    // Someone who typed a dish name wants that dish, whatever their pantry
    // says. Scored once per recipe here rather than inside the comparator,
    // which would recompute it on every comparison.
    if (q) eligible.forEach(function (s) { s._qs = queryScore(s, q); });

    eligible.sort(function (a, b) {
      if (q && b._qs !== a._qs) return b._qs - a._qs;
      // Browsing: quickest first, then alphabetical. Both are about the dish
      // rather than about the kitchen it is being read in.
      if (browsing) {
        if (healthFirst) {
          var ha = headroom(a.recipe), hb = headroom(b.recipe);
          if (ha !== hb) return ha - hb;
        }
        var ta = a.recipe.prepMinutes + a.recipe.cookMinutes;
        var tb = b.recipe.prepMinutes + b.recipe.cookMinutes;
        if (ta !== tb) return ta - tb;
        return a.recipe.name.localeCompare(b.recipe.name);
      }
      if (b.pct !== a.pct) return b.pct - a.pct;
      if (a.missingEssential.length !== b.missingEssential.length) {
        return a.missingEssential.length - b.missingEssential.length;
      }
      return (a.recipe.prepMinutes + a.recipe.cookMinutes) -
             (b.recipe.prepMinutes + b.recipe.cookMinutes);
    });

    renderResults(eligible, blocked, filters, sparse);
  }

  // A plain restatement of what the results are filtered by, so the reader can
  // see it without scrolling back up to the panel. Ingredients and filters take
  // separate labelled rows: run together in one comma list, a filter such as
  // "vegetarian" just reads as one more thing in the pantry.
  function renderSelectedLine(filters) {
    var line = el('selected-line');
    if (!line) return;

    // While searching, the pantry is not narrowing anything, so listing it
    // above the results would claim otherwise.
    var chosen = (selected.size && !searchQuery())
      ? Array.from(selected).map(nameFor).sort().join(', ')
      : '';

    var applied = [];
    if (filters.diets.length) applied.push(filters.diets.map(labelForTag).join(', '));
    if (filters.quickHealthy) applied.push('30 minutes healthy');
    if (filters.maxTime) applied.push('under ' + filters.maxTime + ' minutes');
    if (filters.maxKcal) applied.push('under ' + filters.maxKcal + ' kcal a serving');

    if (!chosen && !applied.length) { line.hidden = true; line.innerHTML = ''; return; }

    function row(label, text, alt) {
      return '<span class="selected-row">' +
               '<span class="selected-label' + (alt ? ' alt' : '') + '">' + label + '</span> ' +
               esc(text) +
             '</span>';
    }

    var html = '';
    if (chosen) html += row('Selected', chosen, false);
    // · passes through esc() untouched, so no entity round-trip needed.
    if (applied.length) html += row('Filters', applied.join(' · '), true);

    line.hidden = false;
    line.innerHTML = html;
  }

  // Delegated once, so cards redrawn on every keystroke need no re-binding.
  document.addEventListener('click', function (ev) {
    var b = ev.target.closest && ev.target.closest('.kcal-toggle');
    if (!b) return;
    ev.preventDefault();
    ev.stopPropagation();
    var panel = document.getElementById(b.getAttribute('aria-controls'));
    if (!panel) return;
    var open = b.getAttribute('aria-expanded') === 'true';
    b.setAttribute('aria-expanded', open ? 'false' : 'true');
    panel.hidden = open;
  });

  function renderResults(eligible, blocked, filters, sparse) {
    // Same test as update()'s, recomputed rather than threaded through: a
    // search or a course filter means the pantry read-out on each card is
    // noise, since the pantry did not decide what is on the page.
    var browsing = !!searchQuery() || filters.quickHealthy ||
                   filters.diets.indexOf('soup') !== -1 ||
                   filters.diets.indexOf('wellness-shot') !== -1;
    var out = el('results');
    out.innerHTML = '';
    renderSelectedLine(filters);

    var hidden = (sparse || []).length;
    var summary = el('results-summary');
    var q = searchQuery();
    // A screenful at a time, with a button for the rest.
    var PAGE = 20;

    // "Showing 20 of 20" is noise, and so is a running total once the reader
    // has everything. Only mention the total while some of it is still hidden.
    function countPhrase(drawn, total) {
      var noun = ' recipe' + (total === 1 ? '' : 's');
      return drawn < total ? 'Showing first ' + drawn + ' of ' + shown(total) + noun
                           : shown(total) + noun;
    }

    function setSummary(drawn) {
      var total = eligible.length;
      if (q) {
        summary.textContent = total === 0
          ? 'No recipe matches \u201c' + q + '\u201d within your filters.'
          : countPhrase(drawn, total) + ' matching \u201c' + q + '\u201d.';
      } else if (browsing) {
        // A filtered browse is not a pantry result, so it does not claim to
        // be one. "You can mostly make" would be a lie about a list the
        // pantry had no part in choosing.
        summary.textContent = countPhrase(drawn, total) + '.';
      } else if (selected.size === 0) {
        summary.textContent = countPhrase(drawn, total) +
          '. Tick what is in your kitchen to rank them by your pantry.';
      } else {
        // The sentence explaining what was withheld and why has gone. It was
        // accurate but it was three lines of small print above the results,
        // and the ranking already makes the point: what is shown is what you
        // can mostly make.
        summary.textContent = countPhrase(drawn, total) + ' you can mostly make.';
      }
    }

    if (eligible.length === 0) {
      var none = document.createElement('p');
      none.className = 'no-results';
      none.textContent = hidden
        ? 'Nothing reaches ' + MIN_PCT + '% of its ingredients from your pantry yet. ' +
          'Tick a few more staples, or loosen the time and dietary filters.'
        : 'Nothing fits those constraints yet. Try loosening the time limit or the dietary filters.';
      out.appendChild(none);
    }

    // The list is ranked, so the tail is the part the cook can least make.
    // Twenty is about a screen and a half; revealing the rest a page at a time
    // keeps the DOM small. The summary is rewritten on each page so it never
    // goes stale against what is actually on screen.
    var drawn = 0;

    var more = document.createElement('button');
    more.type = 'button';
    more.className = 'show-more';

    function draw() {
      eligible.slice(drawn, drawn + PAGE).forEach(function (s) {
        out.insertBefore(card(s, browsing || selected.size === 0), more);
      });
      // Cards ship with an empty heart; this fills in the ones already saved.
      if (window.KhaanaSaved) window.KhaanaSaved.paintExisting();
      drawn = Math.min(drawn + PAGE, eligible.length);
      var left = eligible.length - drawn;
      if (left <= 0) {
        more.remove();
      } else {
        more.textContent = 'Show ' + Math.min(PAGE, left) + ' more (' + shown(left) + ' left)';
      }
      setSummary(drawn);
    }

    out.appendChild(more);
    more.addEventListener('click', draw);
    draw();

    renderNearMisses(blocked, q);
  }

  // How many near misses are worth naming. Ten is a glance; the list used to
  // run to 636 rows and 17,000 pixels, which is not a footnote, it is a
  // second page of results nobody asked for.
  var NEAR_MISS_MAX = 10;

  /* The dishes a filter took away that the reader would want back.
   *
   * Not every exclusion qualifies. A recipe that fails on kind — not a soup,
   * not vegan — is simply a different dish, and listing it says only that the
   * filter did what it was asked. What is worth surfacing is the dish that
   * passed everything the reader asked for and then missed on a threshold:
   * the soup that takes forty minutes, the biryani over the hour. Those are
   * decisions the reader might make differently if they knew.
   *
   * Ranked by what the reader is actually doing, so the ten are the ten most
   * likely to matter: what they searched for first, then what their pantry
   * can nearly make, then the smallest miss. */
  function renderNearMisses(blocked, q) {
    var bwrap = el('blocked');
    bwrap.innerHTML = '';

    var near = blocked.filter(function (s) {
      return s.excluded.length && s.excluded.every(function (e) { return e.kind === 'fit'; });
    });
    if (!near.length) return;

    if (q) near.forEach(function (s) { if (s._qs == null) s._qs = queryScore(s, q); });

    near.sort(function (a, b) {
      if (q && b._qs !== a._qs) return b._qs - a._qs;
      if (a.excluded.length !== b.excluded.length) return a.excluded.length - b.excluded.length;
      if (selected.size > 0 && b.pct !== a.pct) return b.pct - a.pct;
      return (a.recipe.prepMinutes + a.recipe.cookMinutes) -
             (b.recipe.prepMinutes + b.recipe.cookMinutes);
    });

    var picked = near.slice(0, NEAR_MISS_MAX);
    var h = document.createElement('h3');
    h.className = 'blocked-head';
    // Says plainly when it is a selection rather than the whole set, because
    // "(10)" over a trimmed list is a quiet lie about how many there are.
    h.textContent = near.length > picked.length
      ? 'Just missed your filters (' + picked.length + ' of ' + shown(near.length) + ')'
      : 'Just missed your filters (' + picked.length + ')';
    bwrap.appendChild(h);

    picked.forEach(function (s) {
      var p = document.createElement('p');
      p.className = 'blocked-row';
      p.innerHTML = '<a href="recipes/' + s.recipe.id + '.html">' + esc(s.recipe.name) +
        '</a> <span>' + esc(s.excluded.map(function (e) { return e.text; }).join(' / ')) +
        '</span>';
      bwrap.appendChild(p);
    });
  }

  /* `searching` strips the pantry read-out. Also passed when the pantry is
     empty: "0%" and "0/12 ingredients on hand" on every card is noise, and it
     reads as a verdict on the recipe rather than on an untouched pantry. Search and the pantry are two
     independent ways in, so a searched result should not be scored against a
     pantry the reader may not have been using: with the four-item starter
     pantry every hit otherwise showed "13%" and a long Missing list, which
     reads as though the search had been filtered by it. */
  /* Calories are shown on every card by default, with the serving weight so the
     figure means something. The rest of the panel is one click away rather than
     four more lines on every card in a list of twenty. */
  function nutritionRow(r) {
    var n = r.nutrition;
    if (!n) return '';
    var id = 'nut-' + r.id;
    // Anything unweighable is counted as zero, so those figures are floors, not
    // estimates. A + says the real number is higher rather than pretending the
    // arithmetic is complete.
    // No "+" on the numbers. It marked the two thirds of recipes whose figure
    // is a floor rather than an estimate, which was accurate and which nobody
    // else does, so it read as a typo or a footnote marker rather than as
    // information. The caveat stays, in words, under the panel that opens.
    var plus = '';
    var note = n.direction === 'understated'
      ? 'An estimate. Ingredients added to taste are not counted, so the real figure is a little higher.'
      : n.direction === 'overstated'
        ? 'An estimate, and likely lower in practice: much of what is weighed here is not eaten.'
        : 'An estimate, worked out from the listed quantities.';
    return '<div class="kcal-row">' +
             // Protein sits inside the same bracket as the serving weight so
             // that "a serving" governs it too. As its own pill alongside, the
             // number read as if it might be per 100 g.
             //
             // The per-100 g calories moved into the detail below. With it on
             // this line the row ran to three lines on every card, and of the
             // three figures it is the one that compares dishes rather than
             // describing the plate in front of you.
             '<span class="kcal-main"><strong>' + n.kcal + plus + ' kcal</strong> a serving' +
               ' <span class="kcal-weight">(' + n.servingGrams + ' g' +
               (proteinBand(n)
                 ? ' &middot; <span class="kcal-protein" data-band="' + proteinBand(n) +
                   '">' + n.protein.toFixed(0) + plus + ' g protein</span>'
                 : '') +
               ')</span></span>' +
             '<button type="button" class="kcal-toggle" aria-expanded="false" ' +
               'aria-controls="' + id + '">Nutrition</button>' +
           '</div>' +
           '<div class="kcal-detail" id="' + id + '" hidden>' +
             '<span><b>' + n.protein.toFixed(1) + plus + ' g</b> protein</span>' +
             '<span><b>' + n.carbs.toFixed(1) + plus + ' g</b> carbs</span>' +
             '<span><b>' + n.fibre.toFixed(1) + plus + ' g</b> fibre</span>' +
             '<span><b>' + n.fat.toFixed(1) + plus + ' g</b> fat</span>' +
             '<span><b>' + n.satFat.toFixed(1) + plus + ' g</b> saturated</span>' +
             (n.kcal100 ? '<span><b>' + n.kcal100 + plus + ' kcal</b> per 100 g</span>' : '') +
             '<p class="kcal-note">' + esc(note) + ' Full detail on the recipe page.</p>' +
           '</div>';
  }

  function card(s, searching) {
    var r = s.recipe;
    // An <article> rather than an <a>: the nutrition toggle is a real button,
    // and a button inside a link is invalid and unusable by keyboard. The whole
    // card stays clickable through a stretched link on the title.
    var a = document.createElement('article');
    a.className = 'match-card';

    var have = s.lines.filter(function (l) { return !l.staple && l.state === 'have'; }).length;
    var countable = s.lines.filter(function (l) { return !l.staple; }).length;

    // "+3 more" used to be plain text. It sits under the stretched link that
    // makes the whole card clickable, so pressing it opened the recipe instead
    // of showing the rest. It is a real button now, and the full list ships
    // hidden beside it rather than being fetched again.
    // Heaviest shelf first, because this list is cut off at four: a card that
    // says "Missing: ajwain, bay leaf, clove, mace" and hides the mutton
    // behind "+3 more" has buried the only line that matters.
    var missAll = s.missingAll.slice().sort(function (x, y) {
      return (y.weight || 0) - (x.weight || 0);
    }).map(function (l) { return esc(l.name); });
    var missBits = missAll.slice(0, 4).join(', ');
    var extraMiss = missAll.length > 4
      ? '<span class="miss-rest" hidden>, ' + missAll.slice(4).join(', ') + '</span>' +
        '<button type="button" class="miss-more">+' + (missAll.length - 4) + ' more</button>'
      : '';

    var subLines = s.lines.filter(function (l) { return l.state === 'substitute'; });

    var thumb = r.image
      ? '<img src="' + esc(r.image.src) + '" alt="' + esc(r.image.alt) + '" loading="lazy" />'
      : '<span class="match-noimg" aria-hidden="true">' + esc(r.name.charAt(0)) + '</span>';

    a.innerHTML =
      '<div class="match-thumb">' + thumb +
        '<button type="button" class="save-btn save-btn-compact" data-save-id="' +
          esc(r.id) + '" aria-pressed="false" aria-label="Save this recipe"></button>' +
        (searching ? '' :
          '<span class="match-pct" data-tier="' + tier(s.pct) + '">' + s.pct + '%</span>') +
      '</div>' +
      '<div class="match-body">' +
        '<div class="match-meta">' + esc(r.region) + ' &middot; ' + esc(r.difficulty) +
          ' &middot; ' + (r.prepMinutes + r.cookMinutes) + ' min' + waitNote(r) +
          ' &middot; serves ' + r.servings + '</div>' +
        '<h3><a class="match-link" href="recipes/' + esc(r.id) + '.html">' +
          esc(r.name) + '</a></h3>' +
        // Calories and protein sit with the name rather than below the
        // description, because they are what a reader scanning a column of
        // cards is comparing between them.
        nutritionRow(r) +
        '<p class="match-sub">' + esc(r.subtitle) + '</p>' +
        '<div class="diet-tags">' + cardTags(r.tags, r.tagsConditional) + '</div>' +
        (searching ? '' :
        '<div class="match-lines">' +
          '<div class="ml have"><strong>' + have + '/' + countable + '</strong> ingredients on hand</div>' +
          (subLines.length ? '<div class="ml sub"><strong>' + subLines.length +
             '</strong> can be substituted: ' + subLines.map(function (l) {
               return esc(l.name) + ' &rarr; ' + esc(nameFor(l.via.id));
             }).join('; ') + '</div>' : '') +
          (s.missingAll.length ? '<div class="ml miss"><strong>Missing:</strong> ' + missBits + extraMiss + '</div>'
                               : '<div class="ml none">Nothing missing</div>') +
        '</div>') +
      '</div>';
    return a;
  }

  /* Protein band. Two tests, because either alone misleads.
     Grams alone rewards a big portion: dal baati churma reaches 30 g while
     protein is a tenth of 1,215 kcal. Share of calories alone rewards the
     absence of calories: a glass of sambharam is 23% protein and 2.3 g.
     High needs both. The EU threshold for a "high protein" claim is 20% of
     energy, which on this catalogue would pass 186 dishes and only 6
     vegetarian ones, so it is used as a floor rather than the test. */
  function proteinBand(n) {
    if (!n || !n.kcal || typeof n.protein !== 'number') return null;
    var share = (n.protein * 4) / n.kcal;
    if (n.protein >= 20 && share >= 0.12) return 'high';
    if (n.protein >= 10) return 'medium';
    return 'low';
  }
  var PROTEIN_LABEL = { high: 'High protein', medium: 'Medium protein or better',
                        low: 'Low protein' };

  // Delegated, because cards are re-rendered on every filter change.
  document.addEventListener('click', function (ev) {
    var b = ev.target.closest && ev.target.closest('.miss-more');
    if (!b) return;
    ev.preventDefault();
    ev.stopPropagation();
    var rest = b.parentNode.querySelector('.miss-rest');
    if (rest) rest.hidden = false;
    b.remove();
  });

  /* Which diet pills to print on a card.

     Two steps. First drop anything another tag already tells you: vegan means
     vegetarian, dairy-free and egg-free, and vegetarian on this site excludes
     egg, so it means egg-free too. Checked against the whole database, that
     holds for every recipe with no exceptions, and it takes the worst card
     from eight pills to seven.

     Then cap at five, most telling first, because past that the strip wraps
     onto a second line and every wrapped line is a line of card height. The
     count of what is left is shown rather than hidden, and the recipe page
     lists all of them. */
  var TAG_IMPLIES = {
    vegan: ['vegetarian', 'dairy-free', 'egg-free', 'pescatarian'],
    vegetarian: ['egg-free', 'pescatarian']
  };
  var TAG_ORDER = ['vegan', 'vegetarian', 'pescatarian', 'gluten-free', 'dairy-free',
                   'nut-free', 'egg-free', 'no-onion-garlic', 'healthier'];
  var CARD_TAG_LIMIT = 5;

  // conditional: tags that hold only if you leave an optional ingredient out.
  // Khaman Dhokla is vegan without its optional yogurt, and a flat "vegan"
  // pill on the card describes a dish the recipe does not quite print.
  function cardTags(tags, conditional) {
    var cond = {};
    (conditional || []).forEach(function (t) { cond[t] = true; });
    var hide = {};
    tags.forEach(function (t) {
      (TAG_IMPLIES[t] || []).forEach(function (h) { hide[h] = true; });
    });
    var keep = tags.filter(function (t) { return !hide[t]; })
      .sort(function (a, b) {
        var ia = TAG_ORDER.indexOf(a), ib = TAG_ORDER.indexOf(b);
        return (ia < 0 ? 99 : ia) - (ib < 0 ? 99 : ib);
      });
    var extra = keep.length - CARD_TAG_LIMIT;
    var out = keep.slice(0, CARD_TAG_LIMIT).map(function (t) {
      return '<span class="diet-tag' + (cond[t] ? ' diet-tag-opt' : '') + '">' +
             esc(labelForTag(t)) + (cond[t] ? ' option' : '') + '</span>';
    }).join('');
    if (extra > 0) out += '<span class="diet-tag more">+' + extra + '</span>';
    return out;
  }

  function tier(p) { return p >= 90 ? 'high' : p >= 65 ? 'mid' : 'low'; }

  function esc(s) {
    return String(s == null ? '' : s)
      .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  }

  /* ---------- persistence ---------- */

  function persist() {
    try { localStorage.setItem(STORAGE_KEY, JSON.stringify(Array.from(selected))); }
    catch (e) { /* private mode; not worth surfacing */ }
  }
  function restore() {
    try {
      var raw = localStorage.getItem(STORAGE_KEY);
      if (raw) {
        // A saved pantry wins, including a deliberately emptied one — clearing
        // writes "[]", which is distinct from never having visited.
        JSON.parse(raw).forEach(function (id) { selected.add(id); });
        return;
      }
    } catch (e) { /* private mode; fall through to the default */ }
    DEFAULT_PANTRY.forEach(function (id) { selected.add(id); });
  }

  /* ---------- boot ---------- */

  /* The small-screen panel toggle. The label carries the pantry count so the
     button says what is behind it without opening it. */
  function syncPanelToggle() {
    var btn = el('panel-toggle');
    if (!btn) return;
    var n = selected.size;
    var diets = document.querySelectorAll('input[name="diet"]:checked').length;
    var kcal = (el('f-kcal') || {}).value;
    var prot = (el('f-protein') || {}).value;
    var extras = diets + (kcal ? 1 : 0) + (prot ? 1 : 0) +
                 ((el('f-quick') || {}).checked ? 1 : 0) +
                 ((el('f-time') || {}).value ? 1 : 0);
    var bits = [];
    bits.push(n ? n + ' ingredient' + (n === 1 ? '' : 's') : 'nothing chosen yet');
    if (extras) bits.push(extras + ' filter' + (extras === 1 ? '' : 's'));
    btn.innerHTML = '<span>Select ingredients and filters</span>' +
                    '<span class="panel-toggle-count">' + esc(bits.join(' \u00b7 ')) + '</span>';
  }

  /* The Saved filter stays out of the way until it would do something. An
     empty "Saved only" box on a first visit is a control that can only ever
     return nothing. */
  function syncSaved() {
    if (!window.KhaanaSaved) return;
    var n = window.KhaanaSaved.count();
    var wrap = el('saved-filter-wrap'), box = el('f-saved'), c = el('saved-count');
    if (!wrap) return;
    wrap.hidden = n === 0;
    if (c) c.textContent = n;
    if (n === 0 && box && box.checked) { box.checked = false; update(); }
  }

  function wire() {
    var savedBox = el('f-saved');
    if (savedBox) savedBox.addEventListener('change', update);
    document.addEventListener('khaana:saved-changed', function () {
      syncSaved();
      if (el('f-saved') && el('f-saved').checked) update();
    });

    var toggle = el('panel-toggle');
    if (toggle) {
      toggle.addEventListener('click', function () {
        var panel = el('cook-panel');
        var open = panel.classList.toggle('open');
        toggle.setAttribute('aria-expanded', open ? 'true' : 'false');
      });
    }

    document.querySelectorAll('input[name="diet"]').forEach(function (i) {
      i.addEventListener('change', update);
    });
    var quick = el('f-quick');
    if (quick) quick.addEventListener('change', update);
    ['f-time', 'f-kcal', 'f-protein'].forEach(function (id) {
      var s = el(id);
      if (s) s.addEventListener('change', update);
    });
    el('clear-pantry').addEventListener('click', function () {
      selected.clear();
      persist();
      renderPantry();
      update();
    });
    var recipeSearch = el('recipe-search');
    if (recipeSearch) {
      /* Every keystroke re-scores and redraws all 656 recipes. That is about
       * 20ms on a desktop and three to five times that on the cheap Android
       * this site is mostly read on, which is enough to make typing feel like
       * it is dragging. Coalescing a fast typist's run of keystrokes into one
       * render costs nothing a reader can perceive — 120ms is below the
       * threshold where a pause reads as lag — and skips the four or five
       * intermediate result sets nobody was going to look at. */
      var typing = null;
      recipeSearch.addEventListener('input', function () {
        clearTimeout(typing);
        typing = setTimeout(update, 120);
      });
      recipeSearch.addEventListener('search', update);   // the native clear button
    }
    var clearSearch = el('clear-search');
    if (clearSearch) {
      clearSearch.addEventListener('click', function () {
        recipeSearch.value = '';
        recipeSearch.focus();
        update();
      });
    }

    /* ?q= prefills the box. A search on this page used to leave no trace in
     * the URL, so a result could not be linked, bookmarked or sent to anyone —
     * and the site could not honestly declare a search endpoint to a search
     * engine, which is what puts a site-search box under a listing. */
    if (recipeSearch && window.location.search) {
      var m = /[?&]q=([^&]*)/.exec(window.location.search);
      if (m) {
        try { recipeSearch.value = decodeURIComponent(m[1].replace(/\+/g, ' ')); }
        catch (e) { recipeSearch.value = m[1]; }
      }
    }

    var search = el('pantry-search');
    search.addEventListener('input', function () {
      var q = search.value.trim().toLowerCase();
      document.querySelectorAll('.pantry-group').forEach(function (g) {
        var any = false;
        g.querySelectorAll('.ing').forEach(function (l) {
          var hit = !q || l.textContent.toLowerCase().indexOf(q) !== -1;
          l.style.display = hit ? '' : 'none';
          if (hit) any = true;
        });
        g.style.display = any ? '' : 'none';
        // A match inside a folded category is no use folded away.
        if (g.tagName === 'DETAILS') g.open = !!q && any;
      });
    });

    el('add-shelf').addEventListener('click', function () {
      var on = shelfHeld() !== SHELF.length;
      SHELF.forEach(function (id) {
        if (on) selected.add(id); else selected.delete(id);
        syncChecks(id, on);
      });
      persist();
      renderPicked();
      shelfButton();
      update();
    });
  }

  function fail(msg) {
    el('results-summary').textContent = msg;
  }

  Promise.all([
    fetch(PANTRY_URL).then(function (r) { return r.json(); }),
    fetch(RECIPES_URL).then(function (r) { return r.json(); })
  ]).then(function (res) {
    pantry = res[0];
    recipes = res[1].recipes;
    restore();
    renderPantry();
    wire();
    update();
  }).catch(function (e) {
    fail('Could not load the recipe database. If you are opening this file directly, run it through a web server instead: browsers block fetch() on file:// URLs.');
    if (window.console) console.error(e);
  });
})();
